using System;

namespace Crashverse.Data
{
    // JSON-serialisable content models (Unity JsonUtility: public fields, [Serializable], no dictionaries).
    // Source of truth: design/Design_Pack_v1_Ch1_Powerups_LiveOps.md; generated by Tools/ContentGen/gen_content.py.

    [Serializable] public class Reward { public string type; public int amount; public string id; }

    [Serializable] public class MasteryGoal { public string type; public float value; public string role; public string text; }

    [Serializable] public class SlotRule { public string slot; public string powerup; }

    [Serializable]
    public class RuleModifiers
    {
        public float steelJointMult, woodHpMult, brickHpMult, steelHpMult, gravityScale; // 0 = unchanged
        public int shotDelta;
        public static float M(float v) => v <= 0f ? 1f : v;
    }

    [Serializable]
    public class LevelEntry
    {
        public string id; public int number; public string island; public string name; public string layout;
        public string objective; public int shots; public float winThreshold = 0.85f; public string[] materials; // winThreshold: OQ-X1 per-level, default 0.85
        public string teaches; public MasteryGoal mastery; public SlotRule[] forced; public string[] lockedSlots;
        public string requires; public string bossId; public Reward[] reward;
        public float star3Pct = 0.60f; public float star2Pct = 0.30f; public int starCapIfPowerupUsed = 3; public float islandKillY = -2f; // SG-21
        public string hintTarget; public float hintYaw; public float hintPitch; // Addendum v1.1 §1
        public bool HasHint => !string.IsNullOrEmpty(hintTarget);
        public bool IsBoss => !string.IsNullOrEmpty(bossId);
    }

    [Serializable] public class IslandData { public string id; public string name; public float[] pos; public string gateAfterLevel; }

    [Serializable]
    public class ChapterData
    {
        public string id; public string name; public string nextRegion;
        public IslandData[] islands; public LevelEntry[] levels;
    }

    [Serializable]
    public class BlockData
    {
        public string id; public string mat; public float[] p; public float[] s; public string[] sup;
        public bool joint; public string role; public bool nonObj; public string color; public bool explosive;
        public bool indestructible; public float[] spinAxis; public float[] pivot; public float spinDps;
    }

    [Serializable] public class LayoutData { public string id; public BlockData[] blocks; }

    [Serializable]
    public class PowerUpParams
    {
        public float damage; public int linkDepth; public int count; public float damageMult; public float radius;
        public float duration; public float burstDamage; public int passCount; public float slowFactor;
        // Power-ups v2 (design/Powerups_v2_Spec.md): sim-tick durations (0.02 s), Shield refund threshold, Guided Rocket steering.
        public int durationTicks; public float threshold; public float turnRate; public int steerTicks;
    }

    [Serializable]
    public class PowerUpData
    {
        public string id; public string name; public string slot; public string effect; public int charges;
        public string unlockType; public string unlockLevelId; public string unlockText; public PowerUpParams p;
    }

    [Serializable] public class PowerUpCatalog { public PowerUpData[] powerups; }

    [Serializable] public class TitanArena { public string id; public string name; public string layout; public string hintTarget; public float hintYaw, hintPitch; }
    [Serializable] public class TitanRule { public string id; public string text; public RuleModifiers mod; }

    [Serializable]
    public class TitanTemplates
    {
        public string archetype; public string name; public int resetUtcHour; public int rankedGraceMinutes = 15; public int maxDamageScore;
        public int perShotLeftBonus; public int baseShots; public int offlineShotDamageCap = 5000; public TitanArena[] arenas; public TitanRule[] rules;
        public MasteryGoal mastery; public Reward[] completionRewards; public float topPercent; public int topPercentBonusShards;
    }

    /// <summary>What the (real or local) server returns for today's Daily Titan.</summary>
    [Serializable]
    public class DailyTitanConfig
    {
        public string dayKey; public string archetype; public string name; public string arenaId; public string arenaName;
        public string layout; public string ruleId; public string ruleText; public RuleModifiers mod; public int shots;
        public MasteryGoal mastery; public Reward[] completionRewards; public float topPercent; public int topPercentBonusShards;
        public int maxDamageScore; public int perShotLeftBonus; public long resetsAtUnixUtc;
        public string hintTarget; public float hintYaw, hintPitch; // BUG-08: Titan practice hint
    }

    [Serializable] public class DailyRewardsData { public Reward[] days; }

    [Serializable]
    public class WeeklyEvent { public string id; public string name; public string ruleText; public RuleModifiers mod; public LevelEntry[] levels; }

    [Serializable] public class SeasonTier { public int tier; public int xp; public Reward free; public Reward premium; }

    [Serializable]
    public class SeasonData
    {
        public string id; public string name; public string startUtc; public int weekDays; public int xpPerEventStar;
        public int xpPerTitanClear; public int eventStarCapPerLevel = 3; public int bonusChestEveryXp = 300; public int bonusChestCap = 10;
        public int unclaimedInboxDays = 30; public WeeklyEvent[] weeks; public LevelEntry finale; public SeasonTier[] tiers;
    }

    [Serializable]
    public class StoreItem
    {
        public string sku; public string name; public string type; public bool cosmetic; public string priceType; public int price;
        public string grants; public string[] contents;
        /// <summary>Optional catalog flag that must be on for the item to exist at all (e.g. "enableGemPacks").</summary>
        public string requiresFlag;
    }

    /// <summary>Catalog-level release flags. enableGemPacks is false in v1: gems are earned only (design/Economy_v1_Earned_Gems.md).</summary>
    [Serializable] public class StoreFlags
    {
        public bool enableGemPacks;
        public bool IsOn(string flag) => string.IsNullOrEmpty(flag) || (flag == "enableGemPacks" && enableGemPacks); // unknown flags = off
    }
    /// <summary>Economy v1 (earned-only gems). All values are data (Resources/Data/economy.json), tunable server-side.</summary>
    [Serializable] public class GemSources { public int dailyDay7, titanCompletion, titanTop10Bonus, eventAllCleared, eventAll3Star, guardianFirstClear, seasonEvery5thTier, achievementMin, achievementMax; }
    [Serializable] public class StarMilestone { public int stars; public int gems; }
    [Serializable] public class GemSinks { public int epicSkin, trailOrVfxSkin, frameOrTitle, seasonPremiumTrack; }
    [Serializable] public class EconomyData { public GemSources gemSources = new GemSources(); public StarMilestone[] chapterStarMilestones = new StarMilestone[0]; public GemSinks gemSinks = new GemSinks(); public int[] coinCosmeticRange; }
    [Serializable] public class StoreCatalog { public StoreFlags flags = new StoreFlags(); public string[] allowedTypes; public StoreItem[] items; }

    // ───────────── integration/v2: target UI + local (offline) progression. Data: Resources/Data/meta_v2.json ─────────────
    [Serializable] public class RewardBundle { public int coins, gems, chests; public bool IsEmpty => coins == 0 && gems == 0 && chests == 0; }
    /// <summary>Level complete rewards (local wallet). Gems stay earned-only (Economy v1).</summary>
    [Serializable] public class LevelRewardRules { public int coinsFirstClear = 50, coinsPerStar = 25, replayCoins = 10, gemsFirst3Star = 5, chestEveryLevels = 5, hardBonusCoins = 100, hardBonusGems = 5; }
    [Serializable] public class DailyBossData { public string[] layouts; public string[] names; public int baseShots = 6; public int shotSpread = 2; public float winThreshold = 0.85f; public RewardBundle reward = new RewardBundle(); }
    /// <summary>One of the 4 season themes (map banner, backgrounds, level range). comingSoon = no levels in this build yet.</summary>
    [Serializable] public class SeasonTheme { public string id, name, bg, accent, dark; public int number, firstLevel, lastLevel; public bool comingSoon; }
    [Serializable] public class AchievementDef { public string id, name, text, type, icon; public int target; }
    [Serializable] public class ChestRules { public int coinsMin = 50, coinsMax = 150, gemsChancePct = 25, gems = 2; }
    [Serializable]
    public class MetaV2Data
    {
        public LevelRewardRules levelRewards = new LevelRewardRules(); public DailyBossData dailyBoss = new DailyBossData();
        public SeasonTheme[] seasons = new SeasonTheme[0]; public AchievementDef[] achievements = new AchievementDef[0]; public ChestRules chest = new ChestRules();
        public string[] avatars = new string[0]; public string[] badges = new string[0]; public string[] badgeNames = new string[0];
    }

    /// <summary>Default shot tuning (designer data, not code).</summary>
    [Serializable] public class WreckerTuning { public float defaultDamage = 60; public float launchSpeed = 28; public float projectileMass = 0.8f; public float projectileScale = 0.45f; public float splitSpreadDeg = 8;  public float aimYawDegPerDp = 0.25f; public float aimPitchDegPerDp = 0.15f; }
}
